import Foundation
import Testing
@testable import KumoneCore

@Suite("QQ lyric QRC decryption tests")
struct QQLyricDecryptTests {
    /// Real `GetPlayLyricInfo` payload for 孙燕姿《我不难过》(songID 8136),
    /// captured live 2026-11-09. Guards the Folia DES port: the previous
    /// CommonCrypto 3DES implementation could not decrypt this payload
    /// at all, so every QQ lyric fetch failed ("暂无歌词" for all QQ songs).
    @Test func decryptsRealQRCPayload() {
        let text = QQLyricProvider.qrcDecrypt(hex: Self.qrcHex)
        #expect(text != nil)
        guard let text else { return }
        #expect(text.hasPrefix("<?xml version=\"1.0\" encoding=\"utf-8\"?>"))
        #expect(text.contains("[ti:我不难过 ]"))
        #expect(text.contains("[378,2848]"))
    }

